templates = {name: cv2.imread(f'/root/{name}.png', cv2.IMREAD_GRAYSCALE) for name in ['coin','enemy','turtle']}
frames = sorted(glob.glob('/root/keyframes_*.png'))

for frame in frames:
    img = cv2.imread(frame, cv2.IMREAD_GRAYSCALE)
    print('\n', frame)
    for name, tmpl in templates.items():
        res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
        print(name, 'min', res.min(), 'max', res.max(), 'mean', res.mean())
